#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    int count = (int)n;
    vector<vector<int>> adj0(count);
    for (const vector<long long>& e : edges) {
        adj0[e[0] - 1].push_back((int)e[1] - 1);
        adj0[e[1] - 1].push_back((int)e[0] - 1);
    }
    int full = (1 << count) - 1;
    vector<vector<int>> dist(1 << count, vector<int>(count, -1));
    vector<pair<int, int>> queue;
    for (int v = 0; v < count; v++) {
        dist[1 << v][v] = 0;
        queue.push_back({1 << v, v});
    }
    int answer = 0;
    for (size_t i = 0; i < queue.size(); i++) {
        int mask = queue[i].first, v = queue[i].second;
        if (mask == full) {
            answer = dist[mask][v];
            break;
        }
        for (int w : adj0[v]) {
            int nm = mask | (1 << w);
            if (dist[nm][w] < 0) {
                dist[nm][w] = dist[mask][v] + 1;
                queue.push_back({nm, w});
            }
        }
    }
    cout << answer << "\n";

    return 0;
}

