import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        List<List<Integer>> adj0 = new ArrayList<>();
        for (int v = 0; v < count; v++) adj0.add(new ArrayList<>());
        for (long[] e : edges) {
            adj0.get((int) e[0] - 1).add((int) e[1] - 1);
            adj0.get((int) e[1] - 1).add((int) e[0] - 1);
        }
        int full = (1 << count) - 1;
        int[][] dist = new int[1 << count][count];
        for (int[] row : dist) Arrays.fill(row, -1);
        int[] queueMask = new int[(1 << count) * count];
        int[] queueNode = new int[(1 << count) * count];
        int head = 0, tail = 0;
        for (int v = 0; v < count; v++) {
            dist[1 << v][v] = 0;
            queueMask[tail] = 1 << v;
            queueNode[tail++] = v;
        }
        int answer = 0;
        while (head < tail) {
            int mask = queueMask[head], v = queueNode[head++];
            if (mask == full) {
                answer = dist[mask][v];
                break;
            }
            for (int w : adj0.get(v)) {
                int nm = mask | (1 << w);
                if (dist[nm][w] < 0) {
                    dist[nm][w] = dist[mask][v] + 1;
                    queueMask[tail] = nm;
                    queueNode[tail++] = w;
                }
            }
        }
        System.out.println(answer);
    }
}
